  function renderPage(){setTimeout(()=>{ui.lastView=ui.view;},0);switch(ui.view){case'home':return homePage();case'heroes':return heroesPage();case'summon':return summonPage();case'tower':return towerPage();case'battle':return battlePage();case'base':return basePage();case'workshop':return workshopPage();case'synthesis':return synthesisPage();case'missions':return missionsPage();case'research':return researchPage();case'contracts':return contractsPage();case'market':return marketPage();case'journal':return journalPage();case'settings':return settingsPage();default:return homePage();}}
  function teamCard(h){if(!h)return '<button class="team-placeholder" data-act="edit-squad">'+icon('plus')+'<small>Kahraman seç</small></button>';const st=game.stats(h);return '<div class="team-card rarity-'+h.stars+'" role="button" tabindex="0" data-act="hero" data-id="'+h.id+'" aria-label="'+e(h.name)+' ayrıntıları"><div class="portrait team-art" style="'+artStyle(h.portrait,h)+'"></div><div class="class-chip">'+icon(CLASSES[h.cls].icon)+'</div><span class="level-chip">SV. '+h.level+'</span><div class="team-info">'+stars(h.stars)+'<h3>'+e(h.name)+'</h3><div class="between"><small>'+CLASSES[h.cls].name+'</small><small>'+icon('sword','sm')+' '+st.power+'</small></div><div class="mini-bars">'+meter(100-h.fatigue,100)+'<small>'+(h.injury?'Yaralı '+h.injury:'Hazır')+'</small></div></div></div>';}
